// Draws the cover image of every blog post: public/images/covers/<slug>.<language>.png
//
// A cover is the site's own page furniture (paper, ink, one oxide red, the
// "Dr. Kabongo" wordmark) around a headline and one figure. It is laid out as a
// web page and photographed by a local Chrome, so it uses the site's real
// typefaces. Nothing here is generated by an image model.
//
// Usage:  npm run covers            draw the covers that are missing
//         npm run covers -- --all   redraw every cover
//         npm run covers -- <slug>  redraw one post's covers
//
// Needs Google Chrome (set CHROME to its path if it is somewhere unusual) and a
// connection, for the fonts. The site requires a cover for every post: see
// `coverFor` in lib/blog.ts.

import { execFileSync } from 'node:child_process'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import matter from 'gray-matter'
import { C, designs } from './designs.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const BLOG_DIR = path.join(ROOT, 'content', 'blog')
const PUBLIC_DIR = path.join(ROOT, 'public')
const OUT_DIR = path.join(PUBLIC_DIR, 'images', 'covers')

// 1200 × 630 is the size link previews expect; drawn at 2× so it stays sharp
// when a post page shows it wide.
const WIDTH = 1200
const HEIGHT = 630
const SCALE = 2

const CHROME =
  process.env.CHROME ??
  [
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    '/usr/bin/google-chrome',
    '/usr/bin/chromium',
  ].find((candidate) => fs.existsSync(candidate))

const escapeHtml = (value) =>
  String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

/** A post without a design of its own: its title, split at the first sentence. */
function fallbackDesign(data) {
  const title = String(data.title ?? '')
  const cut = title.search(/[.:?!]\s/)
  const lines = cut === -1 ? [title] : [title.slice(0, cut + 1), title.slice(cut + 2)]
  return {
    eyebrow: data.category ?? 'Blog',
    lines,
    size: title.length > 60 ? 56 : 68,
    figure: () =>
      `<p style="margin:0;max-width:940px;font:400 34px/1.4 'Newsreader',serif;color:${C.ink2}">${escapeHtml(data.excerpt ?? '')}</p>`,
  }
}

function page({ eyebrow, lines, size = 68, figure }) {
  const [first, second] = lines
  return `<!doctype html>
<html><head><meta charset="utf-8">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400;1,6..72,500&display=block" rel="stylesheet">
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; width: ${WIDTH}px; height: ${HEIGHT}px; overflow: hidden; background: ${C.paper}; }
  body { padding: 42px 60px 0; font-family: 'Inter', sans-serif; color: ${C.ink}; -webkit-font-smoothing: antialiased; }
  header { display: flex; align-items: baseline; justify-content: space-between; padding-bottom: 14px; border-bottom: 2px solid ${C.ink}; }
  .eyebrow { font: 500 17px 'JetBrains Mono', monospace; letter-spacing: 0.2em; text-transform: uppercase; color: ${C.ink2}; }
  .mark { font: 500 30px 'Newsreader', serif; letter-spacing: -0.01em; }
  h1 { margin: 26px 0 0; font: 500 ${size}px/1.06 'Newsreader', serif; letter-spacing: -0.022em; white-space: nowrap; }
  h1 span, h1 em { display: block; }
  h1 em { font-style: italic; font-weight: 400; color: ${C.accent}; }
  .figure { position: absolute; left: 60px; bottom: 40px; width: 1080px; height: 290px; display: flex; align-items: flex-end; }
  .figure > * { flex: none; }
  .serif { font-family: 'Newsreader', serif; }
  .sans { font-family: 'Inter', sans-serif; }
  .mono { font-family: 'JetBrains Mono', monospace; font-weight: 500; }
</style></head>
<body>
  <header><span class="eyebrow">${escapeHtml(eyebrow)}</span><span class="mark">Dr. Kabongo</span></header>
  <h1><span>${escapeHtml(first)}</span>${second ? `<em>${escapeHtml(second)}</em>` : ''}</h1>
  <div class="figure">${figure}</div>
</body></html>`
}

function draw(html, file, format) {
  const work = fs.mkdtempSync(path.join(os.tmpdir(), 'cover-'))
  const source = path.join(work, 'cover.html')
  const shot = path.join(work, 'cover.png')
  fs.writeFileSync(source, html)
  execFileSync(
    CHROME,
    [
      '--headless=new',
      '--disable-gpu',
      '--hide-scrollbars',
      '--allow-file-access-from-files',
      `--force-device-scale-factor=${SCALE}`,
      `--window-size=${WIDTH},${HEIGHT}`,
      '--virtual-time-budget=10000',
      `--screenshot=${shot}`,
      pathToFileURL(source).href,
    ],
    { stdio: 'ignore' },
  )
  if (format === 'jpg') {
    // A photograph is far smaller as a JPEG. `sips` ships with macOS.
    execFileSync('sips', ['-s', 'format', 'jpeg', '-s', 'formatOptions', '80', shot, '--out', file], {
      stdio: 'ignore',
    })
  } else {
    fs.copyFileSync(shot, file)
  }
  fs.rmSync(work, { recursive: true, force: true })
}

const args = process.argv.slice(2)
const redrawAll = args.includes('--all')
const only = args.filter((arg) => !arg.startsWith('--'))

if (!CHROME) {
  console.error('Google Chrome was not found. Set CHROME to its path.')
  process.exit(1)
}
fs.mkdirSync(OUT_DIR, { recursive: true })

let drawn = 0
for (const locale of fs.readdirSync(BLOG_DIR)) {
  const dir = path.join(BLOG_DIR, locale)
  if (!fs.statSync(dir).isDirectory()) continue
  for (const name of fs.readdirSync(dir).filter((entry) => entry.endsWith('.mdx'))) {
    const slug = name.replace(/\.mdx$/, '')
    if (only.length > 0 && !only.includes(slug)) continue

    const design = designs[slug]
    const format = design?.format ?? 'png'
    const file = path.join(OUT_DIR, `${slug}.${locale}.${format}`)
    if (fs.existsSync(file) && !redrawAll && only.length === 0) continue

    const { data } = matter(fs.readFileSync(path.join(dir, name), 'utf8'))
    const wording = design?.[locale]
    if (design && !wording) {
      console.error(`${slug}: scripts/covers/designs.mjs has no "${locale}" wording for this post`)
      process.exitCode = 1
      continue
    }
    const spec = design
      ? { ...wording, figure: design.figure(wording).replaceAll('{{public}}', pathToFileURL(PUBLIC_DIR).href) }
      : (() => {
          const fallback = fallbackDesign(data)
          return { ...fallback, figure: fallback.figure() }
        })()

    draw(page(spec), file, format)
    drawn++
    console.log(`drew ${path.relative(ROOT, file)}${design ? '' : '  (title only: no design in designs.mjs)'}`)
  }
}
console.log(drawn === 0 ? 'Every post already has a cover.' : `${drawn} cover${drawn === 1 ? '' : 's'} drawn.`)
